"""[fork 增强] R224 具名行情场景 —— **所有口径测量的固定样本集**。

## 为什么必须是它, 而不是随机游走

用户: 「不允许随机抽取, 必须是精心挑选」。**这条批评是对的, 而且我已经栽过两次**:

  · 用随机游走量红绿节拍的档位分布 —— 400 条**全部**判成 `failing`。
    随机游走没有抬高的低点, 结构上就产不出「蓄势」, 那个测量从一开始就是空的。
  · 用随机抽的因子量相关性 —— 十个因子里有六个是我**独立抽出来的**,
    量出来的"互不相关"只是我的抽样方式, 不是这套系统的性质。当场作废。

随机游走还有个更根本的毛病: **它不含"行情"**。真实价格里有蓄势、有突破、有
主升、有钝化、有破位 —— 这些正是这套系统要判的东西, 而随机游走里一个都没有。
拿它做样本, 等于在一堆没有信号的数据上检验一个信号系统。

所以改成**手工构造的具名场景**: 每一条都能说出它是什么, 也就能逐条核对
"系统对它的读数对不对"。数量少但每条都算数, 而且**可复现、可争论** ——
随机样本没法争论, 具名场景可以("这条不该判成主升浪", 那就改这条或改判定)。

## 约定

  · 每条 ≥ 180 根, 保证 MA120 与压缩持续天数都算得出来
  · 只给 `closes`, ATR 由调用方按同一口径估 —— 场景本身不该绑死某个 ATR 定义
  · 名字就是断言: `蓄势突破前` 这条**必须**被判成压缩/横盘中, 判不出就是系统的问题
"""
from __future__ import annotations

import math

# 日内波动幅度。**这个数是这套样本的命门。**
#
# 第一版给了 0.4%, 结果整套样本全废: ATR 塌到接近 0, 于是任何一根 K 线在
# ATR 尺度上都成了天文数字 —— 「缓慢爬升」被判成"大顶区域 + 涨过头",
# 六态也因为摆幅够不到阈值而卡在 NR/NREA, 16 条里一个 UT/DT 都没有。
#
# A 股日线的典型波动在 2% 上下, 取 2.0%。**不是随机数** —— 用三个不可通约的
# 正弦叠加, 完全可复现, 但形状足够"不规则"以产生像样的 ATR 与高低点。
DAILY = 0.020


def _wob(i: int) -> float:
    """确定性的日内摆动。三个不可通约周期叠加 —— 可复现, 但不会退化成周期图形。"""
    return DAILY * (0.62 * math.sin(i * 1.13)
                    + 0.28 * math.sin(i * 2.71 + 1.1)
                    + 0.10 * math.sin(i * 0.37 + 2.3))


def _flat(n: int, px: float, k0: int = 0) -> list[float]:
    """横盘: 只有日内摆动, 不含趋势。"""
    return [px * (1 + _wob(k0 + i)) for i in range(n)]


def _ramp(n: int, start: float, end: float, k0: int = 0) -> list[float]:
    """匀速段。"""
    return [(start + (end - start) * i / max(1, n - 1)) * (1 + _wob(k0 + i))
            for i in range(n)]


def _accel(n: int, start: float, end: float, power: float = 2.2,
           k0: int = 0) -> list[float]:
    """加速段: 越走越快(power > 1)。主升浪与赶顶用它。"""
    out = []
    for i in range(n):
        t = (i / max(1, n - 1)) ** power
        out.append((start + (end - start) * t) * (1 + _wob(k0 + i)))
    return out


def _decel(n: int, start: float, end: float, k0: int = 0) -> list[float]:
    """减速段: 越走越慢。钝化用它。"""
    return _accel(n, start, end, power=0.45, k0=k0)


# ---------------------------------------------------------------- 场景
#
