def closes(name: str) -> list[float]:
    return SCENARIOS[name][1]


def atrs(cs: list[float], window: int = 14) -> list[float]:
    """与场景配套的 ATR 估计。**只用收盘价**(没有高低价), 所以是个代理量 ——
    但整套测量都用同一个代理, 场景之间就可比。"""
    out = []
    for i in range(len(cs)):
        lo = max(1, i - window + 1)
        seg = [abs(cs[j] - cs[j - 1]) for j in range(lo, i + 1)]
        out.append(max(1e-6, (sum(seg) / len(seg)) * 1.4) if seg else 1e-6)
    return out
